"use client";

import React, { useState, useMemo } from "react";
import { 
  ShieldCheck, FileText, Share2, Printer, Zap, 
  Lock, Clock, Search, Plus, Eye, Download, 
  Trash2, History, QrCode, PenTool, Users, 
  AlertTriangle, Filter, ChevronRight
} from "lucide-react";
import Badge from "@/components/ui/badge/Badge";

/* ========================
   1. CORE TYPES & INTELLIGENCE
======================== */
type DocStatus = "Verified" | "Action Required" | "Expiring" | "Shared Externally" | "Signed";

interface EliteDocument {
  id: string;
  name: string;
  category: "Identity" | "Finance" | "Family" | "Corporate";
  status: DocStatus;
  integrity: number; // AI OCR Match Score
  expiry?: string;
  sensitivity: "High" | "Medium" | "Low";
  size: string;
}

const initialDocs: EliteDocument[] = [
  { id: "1", name: "Passport_Primary.pdf", category: "Identity", status: "Expiring", integrity: 99, expiry: "2026-03-12", sensitivity: "High", size: "3.2MB" },
  { id: "2", name: "Form-16_FY25.pdf", category: "Finance", status: "Verified", integrity: 100, sensitivity: "High", size: "1.1MB" },
  { id: "3", name: "Spouse_Health_ID.jpg", category: "Family", status: "Verified", integrity: 94, sensitivity: "Medium", size: "850KB" },
  { id: "4", name: "Remote_Work_NDA.pdf", category: "Corporate", status: "Signed", integrity: 100, sensitivity: "Medium", size: "1.4MB" },
];

export default function EliteDocumentHub() {
  const [docs, setDocs] = useState<EliteDocument[]>(initialDocs);
  const [activeTab, setActiveTab] = useState("All");

  return (
    <div className="min-h-screen bg-[#F8F9FB] dark:bg-[#05070A] p-6 lg:p-12 space-y-10">
      
      {/* --- SECTION 1: THE INTELLIGENCE HEADER (HUD) --- */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* Compliance Score Bento */}
        <div className="lg:col-span-8 bg-white dark:bg-gray-900 rounded-[3rem] p-10 border border-gray-100 dark:border-gray-800 shadow-sm flex items-center justify-between relative overflow-hidden">
          <div className="relative z-10">
            <div className="flex items-center gap-3 mb-4">
              <span className="bg-emerald-500/10 text-emerald-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest">Trust Level: High</span>
              <div className="flex h-2 w-2 rounded-full bg-emerald-500 animate-pulse" />
            </div>
            <h1 className="text-5xl font-black tracking-tighter leading-none mb-4">
              Identity <br /><span className="text-gray-400 font-medium">Verified.</span>
            </h1>
            <p className="max-w-md text-sm text-gray-500 font-medium leading-relaxed">
              Your document vault is synchronized with company compliance. <br />
              <span className="text-brand-600 font-bold underline cursor-pointer">Update Passport to maintain Elite Status.</span>
            </p>
          </div>
          <div className="hidden md:block text-right">
             <div className="text-6xl font-black text-gray-100 dark:text-gray-800 tracking-tighter">98%</div>
             <p className="text-[10px] font-black uppercase text-gray-400 tracking-[0.2em]">Compliance Score</p>
          </div>
          <ShieldCheck className="absolute -right-8 -bottom-8 w-48 h-48 text-gray-50 dark:text-gray-800 opacity-50" />
        </div>

        {/* Action Quick-Links */}
        <div className="lg:col-span-4 grid grid-rows-2 gap-6">
          <button className="bg-brand-600 rounded-[2.5rem] p-6 text-white flex flex-col justify-between items-start group shadow-xl shadow-brand-500/20">
            <QrCode className="opacity-40 group-hover:scale-110 transition-transform" />
            <div className="text-left">
              <h3 className="font-black text-lg">Generate Share Token</h3>
              <p className="text-[10px] opacity-70 font-bold uppercase tracking-widest">For external verification</p>
            </div>
          </button>
          <button className="bg-gray-900 rounded-[2.5rem] p-6 text-white flex flex-col justify-between items-start group">
            <PenTool className="opacity-40 group-hover:scale-110 transition-transform text-brand-400" />
            <div className="text-left">
              <h3 className="font-black text-lg text-brand-400">Request Document</h3>
              <p className="text-[10px] opacity-70 font-bold uppercase tracking-widest">Instant Letter Issuance</p>
            </div>
          </button>
        </div>
      </div>

      {/* --- SECTION 2: THE OPERATIONAL BAR --- */}
      <div className="flex flex-col md:flex-row justify-between items-center gap-6 bg-white dark:bg-gray-900 p-4 rounded-[2.5rem] border border-gray-100 dark:border-gray-800 shadow-sm">
        <div className="flex gap-2 overflow-x-auto no-scrollbar px-2">
          {["All", "Identity", "Finance", "Family", "Corporate"].map(tab => (
            <button 
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`px-6 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${
                activeTab === tab ? "bg-gray-900 dark:bg-brand-600 text-white" : "text-gray-400 hover:text-gray-900"
              }`}
            >
              {tab}
            </button>
          ))}
        </div>
        <div className="flex items-center gap-4 w-full md:w-auto">
          <div className="relative flex-1 md:w-80">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
            <input 
              placeholder="Search encrypted vault..." 
              className="w-full bg-gray-50 dark:bg-gray-800 border-none rounded-2xl py-3 pl-12 pr-4 text-xs font-bold outline-none focus:ring-2 focus:ring-brand-500/50" 
            />
          </div>
          <button className="bg-brand-600 text-white p-3 rounded-2xl shadow-lg hover:rotate-90 transition-transform">
            <Plus size={24} />
          </button>
        </div>
      </div>

      {/* --- SECTION 3: THE VAULT (DATA GRID) --- */}
      <div className="bg-white dark:bg-gray-900 rounded-[3rem] border border-gray-100 dark:border-gray-800 shadow-sm overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-gray-50/50 dark:bg-gray-800/50 text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">
            <tr>
              <th className="px-10 py-6">Asset Intelligence</th>
              <th className="px-10 py-6">Status / Integrity</th>
              <th className="px-10 py-6">Security Level</th>
              <th className="px-10 py-6 text-right">Operations</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50 dark:divide-gray-800">
            {docs.map((doc) => (
              <tr key={doc.id} className="group hover:bg-gray-50/50 transition-colors duration-300">
                <td className="px-10 py-8">
                  <div className="flex items-center gap-6">
                    <div className="w-14 h-14 bg-gray-100 dark:bg-gray-800 rounded-2xl flex items-center justify-center text-gray-400 group-hover:text-brand-600 transition-colors shadow-inner">
                      <FileText size={24} />
                    </div>
                    <div>
                      <h4 className="text-sm font-black text-gray-900 dark:text-white tracking-tight">{doc.name}</h4>
                      <p className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter mt-1">
                        {doc.category} • {doc.size} {doc.expiry && <span className="text-red-500 ml-2 italic">Expiring soon</span>}
                      </p>
                    </div>
                  </div>
                </td>
                <td className="px-10 py-8">
                  <div className="flex flex-col gap-2">
                    <StatusBadge status={doc.status} />
                    <div className="flex items-center gap-2">
                      <div className="w-16 h-1 bg-gray-100 dark:bg-gray-800 rounded-full overflow-hidden">
                        <div className="h-full bg-emerald-500 transition-all duration-1000" style={{ width: `${doc.integrity}%` }} />
                      </div>
                      <span className="text-[9px] font-bold text-gray-400 uppercase">OCR: {doc.integrity}%</span>
                    </div>
                  </div>
                </td>
                <td className="px-10 py-8">
                  <div className="flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full ${doc.sensitivity === 'High' ? 'bg-red-500' : 'bg-brand-400'}`} />
                    <span className="text-[10px] font-black uppercase text-gray-700 dark:text-gray-300">AES-256 {doc.sensitivity}</span>
                  </div>
                </td>
                <td className="px-10 py-8 text-right">
                   <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-all transform translate-x-4 group-hover:translate-x-0">
                      <ActionIcon icon={<Eye />} title="Secure View" />
                      <ActionIcon icon={<Share2 />} title="External Access" />
                      <ActionIcon icon={<History />} title="Audit Trail" />
                      <ActionIcon icon={<Trash2 />} title="Purge Asset" variant="danger" />
                   </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* --- REUSABLE MICRO-COMPONENTS --- */

const DocStatCard = ({ icon, label, value, color }: any) => (
  <div className="bg-white dark:bg-gray-900 p-8 rounded-[2.5rem] border border-gray-100 dark:border-gray-800 shadow-sm flex flex-col justify-between hover:scale-105 transition-transform cursor-default group">
    <div className={`w-12 h-12 rounded-2xl bg-${color}-50 dark:bg-${color}-500/10 flex items-center justify-center text-${color}-600 mb-6 group-hover:rotate-12 transition-transform`}>
      {icon}
    </div>
    <div>
      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{label}</p>
      <h3 className="text-3xl font-black text-gray-900 dark:text-white mt-1 tracking-tighter">{value}</h3>
    </div>
  </div>
);

const ActionIcon = ({ icon, title, variant = "default" }: any) => (
  <button 
    title={title}
    className={`p-3 rounded-xl transition-all shadow-sm border ${
      variant === 'danger' 
      ? 'bg-red-50 text-red-500 border-red-100 hover:bg-red-500 hover:text-white' 
      : 'bg-white dark:bg-gray-800 text-gray-400 border-gray-100 dark:border-gray-700 hover:border-brand-500 hover:text-brand-600'
    }`}
  >
    {React.cloneElement(icon, { size: 18 })}
  </button>
);

const StatusBadge = ({ status }: { status: DocStatus }) => {
  const styles: any = {
    Verified: "bg-emerald-50 text-emerald-600 border-emerald-100",
    "Action Required": "bg-red-50 text-red-600 border-red-100 animate-pulse",
    Expiring: "bg-amber-50 text-amber-600 border-amber-100",
    "Shared Externally": "bg-purple-50 text-purple-600 border-purple-100",
    Signed: "bg-blue-50 text-blue-600 border-blue-100",
  };
  return (
    <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest border ${styles[status]}`}>
      {status}
    </span>
  );
};